var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

var margin = 40;
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var halfW = (W - 3 * margin) / 2;
                    var originX1 = margin, originY = H - margin;
                    var axisH = H - 2 * margin;
                    ctx.strokeStyle = '#333333';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(originX1, originY);
                    ctx.lineTo(originX1 + halfW, originY);
                    ctx.moveTo(originX1, originY);
                    ctx.lineTo(originX1, originY - axisH);
                    ctx.stroke();
                    ctx.strokeStyle = '#4A90D9';
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    var n = 60;
                    for (var i = 0; i <= n; i++) {
                      var fx = i / n;
                      var fy = Math.exp(fx * 3) / Math.exp(3);
                      var px = originX1 + fx * halfW;
                      var py = originY - fy * axisH;
                      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
                    }
                    ctx.stroke();
                    ctx.fillStyle = '#333333';
                    ctx.font = '12px sans-serif';
                    ctx.fillText('linear scale: curve', originX1, originY + 20);
                    var originX2 = margin * 2 + halfW;
                    ctx.strokeStyle = '#333333';
                    ctx.beginPath();
                    ctx.moveTo(originX2, originY);
                    ctx.lineTo(originX2 + halfW, originY);
                    ctx.moveTo(originX2, originY);
                    ctx.lineTo(originX2, originY - axisH);
                    ctx.stroke();
                    ctx.strokeStyle = '#E8593C';
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(originX2, originY);
                    ctx.lineTo(originX2 + halfW, originY - axisH);
                    ctx.stroke();
                    ctx.fillStyle = '#333333';
                    ctx.fillText('log scale: straight line', originX2, originY + 20);
                  }
                };
